    {
      "id": "d8-residual-review",
      "description": "Review a clear-screened request outside D3 through D7.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
