          }
        ]
      },
      "outcome": "review",
      "onUnknown": "ignore",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
    {
      "id": "o2-critical-supplier-review",
      "description": "Review a critical supplier with a clear sanctions result.",
      "when": {
        "op": "all",
        "conditions": [
          {
